    const add = button('＋', () => onCreate({ name: '', timezone: zone, scheduledFor: zonedISO(`${key}T09:00`, zone), posts: [{ channel: state.channel || 'linkedin', text: '', mediaIds: [], ...(state.accountId ? { accountId: state.accountId } : {}) }] }), 'calendar-add'); add.setAttribute('aria-label', `Create a post for ${key}`); cell.append(add);
